// components/NoteCard.tsx
import React, { useState } from 'react';
import { View, Text, StyleSheet, Pressable, Linking } from 'react-native';
import { commonStyles, colors } from '@/styles/commonStyles';
import { Note } from '@/types/Note'; // Assuming Note type is defined

interface NoteCardProps {
    note: Note;
}

const styles = StyleSheet.create({
    text: {
        fontSize: 16,
        fontWeight: '500',
        color: colors.text,
        marginBottom: 8,
        lineHeight: 24,
    },
});

const NoteCard = ({ note }: NoteCardProps) => {
    const [expanded, setExpanded] = useState(false);
    const toggleExpanded = () => setExpanded(!expanded);

    const linesToShow = note.text.includes('http') ? 4 : 3; // Show 4 lines if URL present
    const displayedText = expanded ? note.text : note.text.split('\n').slice(0, linesToShow).join('\n');

    const urlRegex = /(https?:\/\/[^\s]+)/g;

    return (
        <View style={commonStyles.card}>
            <Text onPress={toggleExpanded} numberOfLines={expanded ? undefined : linesToShow} style={styles.text}>
                {displayedText.split('\n').map((line, index) => {
                    const urlMatch = line.match(urlRegex);
                    if (urlMatch) {
                        const parts = line.split(urlRegex);
                        return (
                            <Text key={index}>
                                {parts.map((part, partIndex) => {
                                    if (part.match(urlRegex)) {
                                        return (
                                            <Text key={partIndex} style={{ color: colors.primary }} onPress={() => Linking.openURL(part)}>
                                                {part}
                                            </Text>
                                        );
                                    } else {
                                        return part;
                                    }
                                })}
                                {index < displayedText.split('\n').length - 1 ? '\n' : ''}
                            </Text>
                        );
                    } else {
                        return <Text key={index}>{line}{index < displayedText.split('\n').length - 1 ? '\n' : ''}</Text>;
                    }
                })}
            </Text>
        </View>
    );
};

export default NoteCard;
```

