-- Create a function to trigger OCR processing
CREATE OR REPLACE FUNCTION trigger_ocr_processing()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  request_id bigint;
  service_role_key text;
BEGIN
  -- Get the service role key from environment
  -- Note: In production, this should be stored securely
  service_role_key := current_setting('app.settings.service_role_key', true);

  -- If service role key is not set, use a placeholder that will be replaced
  IF service_role_key IS NULL OR service_role_key = '' THEN
    service_role_key := 'SUPABASE_SERVICE_ROLE_KEY';
  END IF;

  -- Call the OCR edge function with the new image record
  SELECT supabase_functions.http_request(
    'https://cesmsdnblkdjkskmiqib.supabase.co/functions/v1/ocr-image',
    'POST',
    format('{"Content-Type":"application/json","Authorization":"Bearer %s"}', service_role_key)::jsonb,
    format('{"record":{"id":"%s","recall_id":"%s","content_type":"%s","user_id":"%s","cdn_url":"%s"}}', 
      NEW.id, 
      NEW.recall_id, 
      NEW.content_type, 
      NEW.user_id,
      COALESCE(NEW.cdn_url, ''))::jsonb,
    '10000'
  ) INTO request_id;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- Log the error but don't fail the insert
    RAISE WARNING 'Failed to trigger OCR processing for image %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;

-- Create the trigger
