-- Update the trigger function to not require authentication
-- The edge function will be called without auth, so we need to update it to accept service role calls
CREATE OR REPLACE FUNCTION trigger_recall_embedding_processing()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  request_id bigint;
BEGIN
  -- Call the embedding-recall edge function using pg_net
  -- Note: We're using net.http_post without authentication
  -- The edge function should validate the request internally
  SELECT INTO request_id net.http_post(
    url := 'https://cesmsdnblkdjkskmiqib.supabase.co/functions/v1/embedding-recall',
    headers := jsonb_build_object(
      'Content-Type', 'application/json'
    ),
    body := jsonb_build_object(
      'recall_id', NEW.id::text,
      'text', COALESCE(NEW.text, ''),
      'location', COALESCE(NEW.location, ''),
      'location_primary_type', COALESCE(NEW.location_primary_type, '')
    ),
    timeout_milliseconds := 10000
  );

  -- Log success
  RAISE LOG 'Recall embedding processing triggered for recall % with request_id %', NEW.id, request_id;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- Log the error but don't fail the insert/update
    RAISE WARNING 'Failed to trigger recall embedding processing for recall %: % (SQLSTATE: %)', NEW.id, SQLERRM, SQLSTATE;
    RETURN NEW;
END;
$$;

-- Verify the function was updated
DO $$
BEGIN
  RAISE NOTICE 'Trigger function updated to remove authentication requirement';
END $$;

SELECT pg_get_functiondef(oid) 
FROM pg_proc 
WHERE proname = 'trigger_recall_embedding_processing';

-- Drop the existing trigger function
DROP FUNCTION IF EXISTS trigger_recall_embedding_processing() CASCADE;

-- Create the updated trigger function with proper authentication
CREATE OR REPLACE FUNCTION trigger_recall_embedding_processing()
RETURNS TRIGGER AS $$
DECLARE
  request_id bigint;
  service_role_key text;
BEGIN
  -- Get the service role key from vault or use a placeholder
  -- Note: In production, you should store this in Supabase Vault
  -- For now, we'll use the environment variable approach
  service_role_key := current_setting('app.settings.service_role_key', true);

  -- If not set in settings, we'll construct the URL to use the internal service
  -- Supabase's pg_net extension should automatically use service role when calling internal functions

  -- Call the embedding-recall edge function using pg_net with authentication
  SELECT INTO request_id net.http_post(
    url := 'https://cesmsdnblkdjkskmiqib.supabase.co/functions/v1/embedding-recall',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || coalesce(
        service_role_key,
        current_setting('app.supabase_service_role_key', true),
        ''
      )
    ),
    body := jsonb_build_object(
      'recall_id', NEW.id::text,
      'text', COALESCE(NEW.text, ''),
      'location', COALESCE(NEW.location, ''),
      'location_primary_type', COALESCE(NEW.location_primary_type, '')
    ),
    timeout_milliseconds := 30000
  );

  -- Log success
  RAISE LOG 'Recall embedding processing triggered for recall % with request_id %', NEW.id, request_id;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- Log the error but don't fail the insert/update
    RAISE WARNING 'Failed to trigger recall embedding processing for recall %: % (SQLSTATE: %)', NEW.id, SQLERRM, SQLSTATE;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Recreate the trigger
DROP TRIGGER IF EXISTS trigger_embedding_on_recall_save ON recalls;

CREATE TRIGGER trigger_embedding_on_recall_save
AFTER INSERT OR UPDATE ON recalls
FOR EACH ROW
WHEN (
  (TG_OP = 'INSERT') OR 
  (TG_OP = 'UPDATE' AND (
    NEW.text IS DISTINCT FROM OLD.text OR 
    NEW.location IS DISTINCT FROM OLD.location OR 
    NEW.location_primary_type IS DISTINCT FROM OLD.location_primary_type
  ))
)
EXECUTE FUNCTION trigger_recall_embedding_processing();

