-- Enable pg_net extension if not already enabled
CREATE EXTENSION IF NOT EXISTS pg_net;

-- Create function to trigger process-url edge function
CREATE OR REPLACE FUNCTION trigger_process_url()
RETURNS TRIGGER AS $$
DECLARE
  service_role_key TEXT;
  request_id BIGINT;
BEGIN
  -- Get the service role key from vault
  SELECT decrypted_secret INTO service_role_key
  FROM vault.decrypted_secrets
  WHERE name = 'service_role_key'
  LIMIT 1;

  -- Make async HTTP request to process-url edge function
  SELECT net.http_post(
    url := 'https://cesmsdnblkdjkskmiqib.supabase.co/functions/v1/process-url',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_role_key
    ),
    body := jsonb_build_object(
      'url', NEW.url,
      'recall_url_id', NEW.id
    )
  ) INTO request_id;

  -- Log the request
  RAISE LOG 'Triggered process-url for recall_url_id: %, request_id: %', NEW.id, request_id;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create trigger on recall_urls table
DROP TRIGGER IF EXISTS trigger_process_url_on_insert_update ON recall_urls;

CREATE TRIGGER trigger_process_url_on_insert_update
  AFTER INSERT OR UPDATE OF url ON recall_urls
  FOR EACH ROW
  EXECUTE FUNCTION trigger_process_url();

-- Grant necessary permissions
GRANT USAGE ON SCHEMA net TO postgres, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION trigger_process_url() TO postgres, anon, authenticated, service_role;

