import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.80.0';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface PeopleFinderRequest {
  recall_id: string;
  user_id: string;
  text?: string;
  image_explanation?: string;
}

interface OpenAIResponse {
  choices: {
    message: {
      content: string;
    };
  }[];
  usage?: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

interface OpenAIErrorResponse {
  error: {
    message: string;
    type: string;
    code?: string;
  };
}

/**
 * People Finder Edge Function
 * 
 * This function:
 * 1. Receives recall_id, user_id, text, and image_explanation
 * 2. Uses OpenAI NLP NER to detect names of people from the combined text
 * 3. Eliminates duplicate names and capitalizes first letters
 * 4. Inserts/updates records in the "persons" table (unique constraint: user_id, person_name)
 * 5. Inserts/updates records in the "recall_people" table (unique constraint: user_id, recall_id, person_id)
 * 
 * Features:
 * - Runs asynchronously after ocr-image function completes
 * - Uses OpenAI GPT-4o-mini for cost-effective NER
 * - Proper name capitalization
 * - Handles duplicate names
 * - Upserts to avoid conflicts with unique constraints
 */

Deno.serve(async (req) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  const startTime = Date.now();
  console.log('=== People Finder Edge Function Started ===');
  console.log('Timestamp:', new Date().toISOString());

  try {
    // Parse and validate request body
    let requestBody: PeopleFinderRequest;
    try {
      requestBody = await req.json();
    } catch (parseError) {
      console.error('Failed to parse request body:', parseError);
      return new Response(
        JSON.stringify({ error: 'Invalid JSON in request body' }),
        { 
          status: 400, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    const { recall_id, user_id, text, image_explanation } = requestBody;

    if (!recall_id || !user_id) {
      console.error('Missing required fields: recall_id or user_id');
      return new Response(
        JSON.stringify({ error: 'Missing required fields: recall_id and user_id' }),
        { 
          status: 400, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    console.log('Processing recall ID:', recall_id);
    console.log('User ID:', user_id);

    // Combine text and image_explanation
    const combinedText = [text, image_explanation]
      .filter(Boolean)
      .join(' ')
      .trim();

    if (!combinedText) {
      console.log('No text content to process, skipping people detection');
      return new Response(
        JSON.stringify({ 
          success: true, 
          message: 'No text content to process',
          names: [],
          processingTimeMs: Date.now() - startTime,
        }),
        { 
          status: 200, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    console.log('Combined text length:', combinedText.length);

    // Validate environment variables
    const supabaseUrl = Deno.env.get('SUPABASE_URL');
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
    const openaiApiKey = Deno.env.get('OPENAI_API_KEY');

    if (!supabaseUrl || !supabaseServiceKey) {
      console.error('Missing Supabase configuration');
      return new Response(
        JSON.stringify({ error: 'Server configuration error: Supabase credentials missing' }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    if (!openaiApiKey) {
      console.error('OPENAI_API_KEY not configured');
      return new Response(
        JSON.stringify({ error: 'Server configuration error: OpenAI API key missing' }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    // Initialize Supabase client with service role key for admin access
    const supabase = createClient(supabaseUrl, supabaseServiceKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    });

    // Call OpenAI API for Named Entity Recognition (NER)
    console.log('Calling OpenAI API for NER...');
    console.log('Model: gpt-4o-mini');

    const openaiRequestBody = {
      model: 'gpt-4o-mini',
      messages: [
        {
          role: 'system',
          content: `You are a Named Entity Recognition (NER) system specialized in extracting person names from text. 

Your task:
1. Extract ALL person names (first names, last names, or full names) from the provided text
2. Return ONLY the names, one per line
3. Do NOT include titles (Mr., Mrs., Dr., etc.)
4. Do NOT include fictional characters or brand names
5. Do NOT include pronouns or generic terms
6. If no person names are found, return "NO_NAMES_FOUND"

Examples:
Input: "I met John Smith and Sarah at the park. Dr. Johnson was there too."
Output:
John Smith
Sarah
Johnson

Input: "The weather is nice today."
Output:
NO_NAMES_FOUND`
        },
        {
          role: 'user',
          content: combinedText
        }
      ],
      max_tokens: 300,
      temperature: 0.1, // Very low temperature for consistent extraction
    };

    let openaiResponse;
    let retryCount = 0;
    const maxRetries = 2;

    // Retry logic for transient failures
    while (retryCount <= maxRetries) {
      try {
        openaiResponse = await fetch('https://api.openai.com/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${openaiApiKey}`,
          },
          body: JSON.stringify(openaiRequestBody),
        });

        if (openaiResponse.ok) {
          break; // Success, exit retry loop
        }

        // Handle rate limiting with exponential backoff
        if (openaiResponse.status === 429 && retryCount < maxRetries) {
          const waitTime = Math.pow(2, retryCount) * 1000; // 1s, 2s, 4s
          console.log(`Rate limited. Waiting ${waitTime}ms before retry ${retryCount + 1}/${maxRetries}`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          retryCount++;
          continue;
        }

        // For other errors, break and handle below
        break;
      } catch (fetchError) {
        console.error(`Fetch attempt ${retryCount + 1} failed:`, fetchError);
        if (retryCount < maxRetries) {
          const waitTime = Math.pow(2, retryCount) * 1000;
          console.log(`Waiting ${waitTime}ms before retry ${retryCount + 1}/${maxRetries}`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          retryCount++;
        } else {
          throw fetchError;
        }
      }
    }

    if (!openaiResponse || !openaiResponse.ok) {
      const errorText = await openaiResponse?.text() || 'No response';
      console.error('OpenAI API error response:', errorText);

      let errorMessage = 'OpenAI API request failed';
      try {
        const errorJson = JSON.parse(errorText) as OpenAIErrorResponse;
        errorMessage = errorJson.error?.message || errorMessage;
      } catch {
        errorMessage = errorText.substring(0, 200);
      }

      return new Response(
        JSON.stringify({ 
          error: 'OpenAI API request failed', 
          details: errorMessage,
          status: openaiResponse?.status 
        }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    const openaiData = await openaiResponse.json() as OpenAIResponse;

    if (!openaiData.choices || openaiData.choices.length === 0) {
      console.error('No choices in OpenAI response');
      return new Response(
        JSON.stringify({ error: 'Invalid response from OpenAI API' }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    const responseText = openaiData.choices[0]?.message?.content || '';

    console.log('OpenAI response received');
    console.log('Response:', responseText);
    if (openaiData.usage) {
      console.log('Token usage:', JSON.stringify(openaiData.usage));
    }

    // Parse and process names
    let names: string[] = [];

    if (responseText.trim() !== 'NO_NAMES_FOUND') {
      // Split by newlines and filter empty lines
      const rawNames = responseText
        .split('\n')
        .map(name => name.trim())
        .filter(name => name.length > 0 && name !== 'NO_NAMES_FOUND');

      // Capitalize first letter of each word in each name and remove duplicates
      const capitalizedNames = rawNames.map(name => {
        return name
          .split(' ')
          .map(word => {
            if (word.length === 0) return word;
            return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
          })
          .join(' ');
      });

      // Remove duplicates (case-insensitive comparison)
      const uniqueNames = new Set<string>();
      capitalizedNames.forEach(name => {
        const normalized = name.toLowerCase();
        if (!Array.from(uniqueNames).some(existing => existing.toLowerCase() === normalized)) {
          uniqueNames.add(name);
        }
      });

      names = Array.from(uniqueNames);
    }

    console.log('Extracted names:', names);
    console.log('Total unique names:', names.length);

    // Process each name: upsert into persons and recall_people tables
    const processedNames: string[] = [];
    const errors: string[] = [];

    for (const personName of names) {
      try {
        console.log(`Processing person: ${personName}`);

        // 1. Upsert into persons table
        const { data: person, error: personError } = await supabase
          .from('persons')
          .upsert(
            { 
              user_id: user_id, 
              person_name: personName 
            },
            { 
              onConflict: 'user_id,person_name',
              ignoreDuplicates: false 
            }
          )
          .select('id')
          .single();

        if (personError) {
          console.error(`Error upserting person "${personName}":`, personError);
          errors.push(`Failed to upsert person "${personName}": ${personError.message}`);
          continue;
        }

        if (!person) {
          console.error(`No person data returned for "${personName}"`);
          errors.push(`No person data returned for "${personName}"`);
          continue;
        }

        console.log(`Person "${personName}" upserted with ID:`, person.id);

        // 2. Upsert into recall_people table
        const { data: recallPerson, error: recallPersonError } = await supabase
          .from('recall_people')
          .upsert(
            { 
              user_id: user_id, 
              recall_id: recall_id, 
              person_id: person.id 
            },
            { 
              onConflict: 'user_id,recall_id,person_id',
              ignoreDuplicates: false 
            }
          )
          .select('id')
          .single();

        if (recallPersonError) {
          console.error(`Error upserting recall_person for "${personName}":`, recallPersonError);
          errors.push(`Failed to link person "${personName}" to recall: ${recallPersonError.message}`);
          continue;
        }

        console.log(`Recall-person link created for "${personName}"`);
        processedNames.push(personName);

      } catch (error) {
        console.error(`Exception processing person "${personName}":`, error);
        errors.push(`Exception processing "${personName}": ${error instanceof Error ? error.message : 'Unknown error'}`);
      }
    }

    const processingTime = Date.now() - startTime;
    console.log('=== People Finder processing completed ===');
    console.log('Total processing time:', processingTime, 'ms');
    console.log('Successfully processed:', processedNames.length, 'names');
    console.log('Errors:', errors.length);

    return new Response(
      JSON.stringify({ 
        success: true,
        recall_id: recall_id,
        names: processedNames,
        totalNamesFound: names.length,
        successfullyProcessed: processedNames.length,
        errors: errors.length > 0 ? errors : undefined,
        processingTimeMs: processingTime,
      }),
      { 
        status: 200, 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
      }
    );

  } catch (error) {
    const processingTime = Date.now() - startTime;
    console.error('=== Error in People Finder Edge Function ===');
    console.error('Error type:', error?.constructor?.name);
    console.error('Error message:', error instanceof Error ? error.message : 'Unknown error');
    console.error('Error stack:', error instanceof Error ? error.stack : 'No stack trace');
    console.error('Processing time before error:', processingTime, 'ms');

    return new Response(
      JSON.stringify({ 
        error: 'Internal server error', 
        details: error instanceof Error ? error.message : 'Unknown error',
        processingTimeMs: processingTime,
      }),
      { 
        status: 500, 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
      }
    );
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.80.0';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface ImageRecord {
  id: string;
  recall_id: string;
  content_type: string;
  user_id: string;
  cdn_url?: string;
}

interface OpenAIVisionResponse {
  choices: {
    message: {
      content: string;
    };
  }[];
  usage?: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

interface OpenAIErrorResponse {
  error: {
    message: string;
    type: string;
    code?: string;
  };
}

/**
 * Enhanced OCR and Image Explanation Edge Function
 * 
 * This function:
 * 1. Receives an image record ID from a database webhook or manual trigger
 * 2. Fetches the image CDN URL from the recall_images table
 * 3. Sends the image to OpenAI's Vision API (gpt-4o-mini) for OCR and explanation
 * 4. Parses the response to extract OCR text and explanation separately
 * 5. Updates the database with the results
 * 6. Calls the embedding-image function to generate embeddings for the image
 * 
 * Features:
 * - Robust error handling with detailed logging
 * - Cost-optimized using gpt-4o-mini model
 * - Structured prompt for consistent response format
 * - Automatic retry logic for transient failures
 * - Comprehensive validation and sanitization
 * - Triggers embedding generation after OCR completion
 */

Deno.serve(async (req) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  const startTime = Date.now();
  console.log('=== OCR Image Edge Function Started ===');
  console.log('Timestamp:', new Date().toISOString());

  try {
    // Parse and validate request body
    let requestBody;
    try {
      requestBody = await req.json();
    } catch (parseError) {
      console.error('Failed to parse request body:', parseError);
      return new Response(
        JSON.stringify({ error: 'Invalid JSON in request body' }),
        { 
          status: 400, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    const { record } = requestBody as { record: ImageRecord };

    if (!record || !record.id) {
      console.error('No record or record.id provided in request');
      return new Response(
        JSON.stringify({ error: 'Missing required field: record.id' }),
        { 
          status: 400, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    console.log('Processing image ID:', record.id);
    console.log('Recall ID:', record.recall_id);

    // Validate environment variables
    const supabaseUrl = Deno.env.get('SUPABASE_URL');
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
    const openaiApiKey = Deno.env.get('OPENAI_API_KEY');

    if (!supabaseUrl || !supabaseServiceKey) {
      console.error('Missing Supabase configuration');
      return new Response(
        JSON.stringify({ error: 'Server configuration error: Supabase credentials missing' }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    if (!openaiApiKey) {
      console.error('OPENAI_API_KEY not configured');
      return new Response(
        JSON.stringify({ error: 'Server configuration error: OpenAI API key missing' }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    // Initialize Supabase client with service role key for admin access
    const supabase = createClient(supabaseUrl, supabaseServiceKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    });

    // Fetch the image CDN URL from the database
    console.log('Fetching image CDN URL from database...');
    const { data: imageData, error: fetchError } = await supabase
      .from('recall_images')
      .select('cdn_url, content_type, user_id')
      .eq('id', record.id)
      .single();

    if (fetchError) {
      console.error('Database fetch error:', fetchError);
      return new Response(
        JSON.stringify({ 
          error: 'Failed to fetch image data from database',
          details: fetchError.message 
        }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    if (!imageData) {
      console.error('No image data found for ID:', record.id);
      return new Response(
        JSON.stringify({ error: 'Image data not found in database' }),
        { 
          status: 404, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    console.log('Image data fetched successfully');
    console.log('Content type:', imageData.content_type);
    console.log('Has CDN URL:', !!imageData.cdn_url);
    console.log('User ID:', imageData.user_id);

    // Check if we have a CDN URL
    if (!imageData.cdn_url) {
      console.error('No CDN URL found for ID:', record.id);
      return new Response(
        JSON.stringify({ error: 'Image CDN URL not found in database' }),
        { 
          status: 404, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    console.log('Using CDN URL for OCR processing:', imageData.cdn_url);
    const imageDataUrl = imageData.cdn_url;

    // Call OpenAI Vision API with enhanced prompt
    console.log('Calling OpenAI Vision API...');
    console.log('Model: gpt-4o-mini');
    console.log('Max tokens: 500');

    const openaiRequestBody = {
      model: 'gpt-4o-mini',
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: `Analyze this image and provide two things:

1. OCR TEXT: Extract ALL visible text from the image. If there is no text, write "No text detected."

2. EXPLANATION: Describe what the image shows in under 70 words. Be concise and informative.

Format your response EXACTLY like this:

OCR TEXT:
[extracted text or "No text detected."]

EXPLANATION:
[your description here]`
            },
            {
              type: 'image_url',
              image_url: {
                url: imageDataUrl,
                detail: 'high'
              }
            }
          ]
        }
      ],
      max_tokens: 500,
      temperature: 0.3, // Lower temperature for more consistent results
    };

    let openaiResponse;
    let retryCount = 0;
    const maxRetries = 2;

    // Retry logic for transient failures
    while (retryCount <= maxRetries) {
      try {
        openaiResponse = await fetch('https://api.openai.com/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${openaiApiKey}`,
          },
          body: JSON.stringify(openaiRequestBody),
        });

        if (openaiResponse.ok) {
          break; // Success, exit retry loop
        }

        // Handle rate limiting with exponential backoff
        if (openaiResponse.status === 429 && retryCount < maxRetries) {
          const waitTime = Math.pow(2, retryCount) * 1000; // 1s, 2s, 4s
          console.log(`Rate limited. Waiting ${waitTime}ms before retry ${retryCount + 1}/${maxRetries}`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          retryCount++;
          continue;
        }

        // For other errors, break and handle below
        break;
      } catch (fetchError) {
        console.error(`Fetch attempt ${retryCount + 1} failed:`, fetchError);
        if (retryCount < maxRetries) {
          const waitTime = Math.pow(2, retryCount) * 1000;
          console.log(`Waiting ${waitTime}ms before retry ${retryCount + 1}/${maxRetries}`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          retryCount++;
        } else {
          throw fetchError;
        }
      }
    }

    if (!openaiResponse || !openaiResponse.ok) {
      const errorText = await openaiResponse?.text() || 'No response';
      console.error('OpenAI API error response:', errorText);

      let errorMessage = 'OpenAI API request failed';
      try {
        const errorJson = JSON.parse(errorText) as OpenAIErrorResponse;
        errorMessage = errorJson.error?.message || errorMessage;
      } catch {
        // If parsing fails, use the raw error text
        errorMessage = errorText.substring(0, 200);
      }

      return new Response(
        JSON.stringify({ 
          error: 'OpenAI API request failed', 
          details: errorMessage,
          status: openaiResponse?.status 
        }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    const openaiData = await openaiResponse.json() as OpenAIVisionResponse;

    if (!openaiData.choices || openaiData.choices.length === 0) {
      console.error('No choices in OpenAI response');
      return new Response(
        JSON.stringify({ error: 'Invalid response from OpenAI API' }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    const responseText = openaiData.choices[0]?.message?.content || '';

    console.log('OpenAI response received');
    console.log('Response length:', responseText.length);
    if (openaiData.usage) {
      console.log('Token usage:', JSON.stringify(openaiData.usage));
    }

    // Parse the response to extract OCR text and explanation
    let ocrText = '';
    let explanation = '';

    // Enhanced parsing with multiple fallback strategies
    const ocrMatch = responseText.match(/OCR TEXT:\s*([\s\S]*?)(?=\n\s*EXPLANATION:|$)/i);
    const explanationMatch = responseText.match(/EXPLANATION:\s*([\s\S]*?)$/i);

    if (ocrMatch) {
      ocrText = ocrMatch[1].trim();
      console.log('Extracted OCR text (length):', ocrText.length);
    } else {
      console.warn('Could not parse OCR TEXT section');
    }

    if (explanationMatch) {
      explanation = explanationMatch[1].trim();
      console.log('Extracted explanation (length):', explanation.length);
    } else {
      console.warn('Could not parse EXPLANATION section');
    }

    // Fallback: if parsing completely failed, try alternative format
    if (!ocrText && !explanation) {
      console.log('Primary parsing failed, attempting fallback parsing...');

      // Try splitting by double newline
      const parts = responseText.split(/\n\s*\n/);
      if (parts.length >= 2) {
        ocrText = parts[0].replace(/^OCR TEXT:\s*/i, '').trim();
        explanation = parts.slice(1).join('\n\n').replace(/^EXPLANATION:\s*/i, '').trim();
        console.log('Fallback parsing successful');
      } else {
        // Last resort: use entire response as explanation
        console.log('All parsing failed, using entire response as explanation');
        explanation = responseText.trim();
        ocrText = 'No text detected.';
      }
    }

    // Sanitize and validate results
    ocrText = ocrText.substring(0, 10000); // Limit to 10k chars
    explanation = explanation.substring(0, 2000); // Limit to 2k chars

    console.log('Final OCR text length:', ocrText.length);
    console.log('Final explanation length:', explanation.length);

    // Update the database with OCR results
    console.log('Updating database with results...');
    const { error: updateError } = await supabase
      .from('recall_images')
      .update({
        ocr_text: ocrText,
        image_explanation: explanation,
        processed_at: new Date().toISOString(),
      })
      .eq('id', record.id);

    if (updateError) {
      console.error('Database update error:', updateError);
      return new Response(
        JSON.stringify({ 
          error: 'Failed to update database with OCR results', 
          details: updateError.message 
        }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    const processingTime = Date.now() - startTime;
    console.log('=== OCR processing completed successfully ===');
    console.log('Total processing time:', processingTime, 'ms');

    // Trigger category matching for this recall
    console.log('Triggering category matching for recall:', record.recall_id);
    try {
      const categoryMatchResponse = await fetch(`${supabaseUrl}/functions/v1/match-recollection-category`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${supabaseServiceKey}`,
        },
        body: JSON.stringify({ recallId: record.recall_id }),
      });

      if (categoryMatchResponse.ok) {
        const categoryMatchData = await categoryMatchResponse.json();
        console.log('Category matching triggered successfully:', categoryMatchData);
      } else {
        const errorText = await categoryMatchResponse.text();
        console.error('Failed to trigger category matching:', errorText);
      }
    } catch (categoryError) {
      console.error('Exception while triggering category matching:', categoryError);
      // Don't fail the OCR process if category matching fails
    }

    // ===== TRIGGER EMBEDDING GENERATION FOR THIS IMAGE =====
    // This happens at the end, after OCR processing is complete
    // FIXED: Trigger embedding if EITHER ocr_text OR image_explanation has a value
    console.log('=== Triggering embedding generation for image ===');
    console.log('Image ID:', record.id);

    // Check if we have meaningful content for embedding
    const hasOcrText = ocrText && ocrText !== 'No text detected.' && ocrText.trim().length > 0;
    const hasExplanation = explanation && explanation.trim().length > 0;

    console.log('Has OCR text:', hasOcrText);
    console.log('Has explanation:', hasExplanation);

    // Trigger embedding if we have EITHER ocr_text OR explanation
    if (hasOcrText || hasExplanation) {
      try {
        console.log('Calling embedding-image function...');
        const embeddingResponse = await fetch(`${supabaseUrl}/functions/v1/embedding-image`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${supabaseServiceKey}`,
          },
          body: JSON.stringify({
            recall_image_id: record.id,
            ocr_text: ocrText,
            image_explanation: explanation,
          }),
        });

        if (embeddingResponse.ok) {
          const embeddingData = await embeddingResponse.json();
          console.log('Embedding generated successfully:', embeddingData);
        } else {
          const errorText = await embeddingResponse.text();
          console.error('Failed to generate embedding:', errorText);
          // Don't fail the OCR process if embedding generation fails
        }
      } catch (embeddingError) {
        console.error('Exception while generating embedding:', embeddingError);
        // Don't fail the OCR process if embedding generation fails
      }
    } else {
      console.log('Skipping embedding generation - no meaningful text content (both ocr_text and explanation are empty)');
    }

    console.log('=== Embedding generation triggered ===');

    // ===== TRIGGER PEOPLE FINDER FUNCTION ASYNCHRONOUSLY =====
    // This happens at the end, after OCR processing is complete
    // The people-finder function will extract person names from the text
    console.log('=== Triggering people-finder function asynchronously ===');
    console.log('Recall ID:', record.recall_id);
    console.log('User ID:', imageData.user_id);

    // Fetch the recall text to combine with image explanation
    let recallText = '';
    try {
      const { data: recallData, error: recallError } = await supabase
        .from('recalls')
        .select('text')
        .eq('id', record.recall_id)
        .single();

      if (recallError) {
        console.error('Failed to fetch recall text:', recallError);
      } else if (recallData) {
        recallText = recallData.text || '';
        console.log('Recall text length:', recallText.length);
      }
    } catch (recallFetchError) {
      console.error('Exception fetching recall text:', recallFetchError);
    }

    // Trigger people-finder asynchronously (don't wait for response)
    // We use fetch without await to make it truly asynchronous
    fetch(`${supabaseUrl}/functions/v1/people-finder`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${supabaseServiceKey}`,
      },
      body: JSON.stringify({
        recall_id: record.recall_id,
        user_id: imageData.user_id,
        text: recallText,
        image_explanation: explanation,
      }),
    })
      .then(async (response) => {
        if (response.ok) {
          const data = await response.json();
          console.log('People-finder triggered successfully:', data);
        } else {
          const errorText = await response.text();
          console.error('Failed to trigger people-finder:', errorText);
        }
      })
      .catch((error) => {
        console.error('Exception while triggering people-finder:', error);
      });

    console.log('=== People-finder function triggered asynchronously ===');

    return new Response(
      JSON.stringify({ 
        success: true, 
        imageId: record.id,
        processingTimeMs: processingTime,
        ocrTextLength: ocrText.length,
        explanationLength: explanation.length,
        ocrTextPreview: ocrText.substring(0, 100) + (ocrText.length > 100 ? '...' : ''),
        explanationPreview: explanation.substring(0, 100) + (explanation.length > 100 ? '...' : ''),
        embeddingTriggered: hasOcrText || hasExplanation,
        peopleFinderTriggered: true,
      }),
      { 
        status: 200, 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
      }
    );

  } catch (error) {
    const processingTime = Date.now() - startTime;
    console.error('=== Error in OCR Image Edge Function ===');
    console.error('Error type:', error?.constructor?.name);
    console.error('Error message:', error instanceof Error ? error.message : 'Unknown error');
    console.error('Error stack:', error instanceof Error ? error.stack : 'No stack trace');
    console.error('Processing time before error:', processingTime, 'ms');

    return new Response(
      JSON.stringify({ 
        error: 'Internal server error', 
        details: error instanceof Error ? error.message : 'Unknown error',
        processingTimeMs: processingTime,
      }),
      { 
        status: 500, 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
      }
    );
  }
});
